window.FIG_SERIES=window.FIG_SERIES||{};window.FIG_SERIES["FIG-6a45d8754bdc72b8"]={"versions": [{"id": "FIG-6a45d8754bdc72b8", "releases": ["R17-10_R1.2.0"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">Timing- und Zustandsdiagramm zur Darstellung der zustandsabhängigen Prozesssteuerung (State Dependent Process Control) innerhalb des Execution Management (EM) der AUTOSAR Adaptive Platform. Das Diagramm ordnet die Lebenszyklen und Ausführungszustände von Prozessen den Zuständen der Machine (Machine State) sowie den Zuständen übergeordneter Funktionsgruppen (Function Group State) über einer gemeinsamen horizontalen Zeitachse (t) zu.</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<p class=\"fig-p\">Das Diagramm gliedert sich in Steuerungsebenen und Prozessverläufe:</p>\n<ul class=\"fig-list\"><li>Machine State: Enthält die Zustände Startup, Running, Diagnostics und Shutdown, getrennt durch schraffierte Übergangsphasen (state transition).\n</li><li>Function Group 1 State: Enthält die Zustände FG1:Off, FG1:Running und FG1:Off, getrennt durch schraffierte Zustandsübergänge.\n</li><li>Function Group 2 State: Enthält die Zustände FG2:Off, FG2:Running, FG2:Fallback, FG2:Off, FG2:Diag und FG2:Off, jeweils getrennt durch schraffierte Übergänge.\n</li><li>Prozesse A bis F: Prozesse der Plattform bzw. von Anwendungen mit den drei diskreten Ausführungszuständen Idle, Running und Terminated.\n</li><li>Annotationen und Beziehungen: Referenzen (reference) von Prozessen auf bestimmte Zustände (Startup, Running, FG1:Running, FG2:Running, FG2:Fallback), Startabhängigkeiten (dependency), Kennzeichnung eines One-Shot-Prozesses (one shot) sowie Kennzeichnung abweichender Startparameter/Neustarts über Schnittmarken (different StartupOptions).\n</li></ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<ul class=\"fig-list\"><li>Während des Machine-Zustands Startup startet Prozess A (Idle -&gt; Running) und terminiert nach kurzer Ausführung selbsttätig (Running -&gt; Terminated, one shot).\n</li><li>Prozess B besitzt eine Startabhängigkeit (dependency) auf die Beendigung von Prozess A und wechselt nach dessen Termination von Idle nach Running; er verbleibt running über den Übergang in Machine State Running hinweg bis zum Übergang nach Diagnostics, wo er nach Terminated wechselt.\n</li><li>Beim Eintritt in Machine State Running startet Prozess C (Idle -&gt; Running) und terminiert ebenfalls beim Übergang zu Diagnostics.\n</li><li>Mit Eintritt der Function Group 1 in FG1:Running wird Prozess D gestartet (Idle -&gt; Running) und terminiert beim Verlassen von FG1:Running wieder nach Terminated.\n</li><li>Prozess E startet bei Eintritt in FG1:Running (Idle -&gt; Running) und referenziert zusätzlich FG2:Running; beim Übergang von FG2:Running nach FG2:Fallback terminiert Prozess E.\n</li><li>Prozess F startet bei Eintritt in FG2:Running; beim Übergang von FG2:Running zu FG2:Fallback wird Prozess F mit geänderten StartupOptions (different StartupOptions) neu gestartet bzw. angepasst und terminiert beim Übergang von FG2:Fallback nach FG2:Off.\n</li></ul>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Für Entwickler und Integratoren verdeutlicht das Diagramm die Aktivierungs- und Terminierungsregeln für Prozesse unter Execution Management:</p>\n<ul class=\"fig-list\"><li>Prozesse werden deklarativ an Zustände von Machine States oder Function Group States gebunden (reference).\n</li><li>Ausführungsabhängigkeiten (dependencies) verzögern den Start abhängiger Prozesse innerhalb desselben Systemzustands, bis Vorgängerprozesse erfolgreich initialisiert oder terminiert sind.\n</li><li>Zustandswechsel übergeordneter Funktionsgruppen erzwingen das Starten, Terminieren oder Neustarten mit modifizierten Argumenten/Optionen (different StartupOptions) der zugeordneten Prozesse.\n</li><li>Schraffierte Phasen markieren Transitionsintervalle, in denen das Execution Management Prozesse kontrolliert hoch- bzw. herunterfährt, bevor der Zielzustand als erreicht gilt.\n</li></ul>", "model": "gemini-3.8-flash (via agy)"}, {"id": "FIG-c6b898406a2ae201", "releases": ["R18-03_R1.4.0"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">Timing- und Zustandsdiagramm zur Darstellung der zustandsabhängigen Prozesssteuerung (State Dependent Process Control) innerhalb des Execution Management (EM) der AUTOSAR Adaptive Platform. Das Diagramm ordnet die Lebenszyklen und Ausführungszustände von Prozessen den Zuständen der Machine (Machine State) sowie den Zuständen übergeordneter Funktionsgruppen (Function Group State) über einer gemeinsamen horizontalen Zeitachse (t) zu.</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<p class=\"fig-p\">Das Diagramm gliedert sich in Steuerungsebenen und Prozessverläufe:</p>\n<ul class=\"fig-list\"><li>Machine State: Enthält die Zustände Startup, Running, Diagnostics und Shutdown, getrennt durch schraffierte Übergangsphasen (state transition).\n</li><li>Function Group 1 State: Enthält die Zustände FG1:Off, FG1:Running und FG1:Off, getrennt durch schraffierte Zustandsübergänge.\n</li><li>Function Group 2 State: Enthält die Zustände FG2:Off, FG2:Running, FG2:Fallback, FG2:Off, FG2:Diag und FG2:Off, jeweils getrennt durch schraffierte Übergänge.\n</li><li>Prozesse A bis F: Prozesse der Plattform bzw. von Anwendungen mit den drei diskreten Ausführungszuständen Idle, Running und Terminated.\n</li><li>Annotationen und Beziehungen: Referenzen (reference) von Prozessen auf bestimmte Zustände (Startup, Running, FG1:Running, FG2:Running, FG2:Fallback), Startabhängigkeiten (dependency), Kennzeichnung eines One-Shot-Prozesses (one shot) sowie Kennzeichnung abweichender Startparameter/Neustarts über Schnittmarken (different StartupOptions).\n</li></ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<ul class=\"fig-list\"><li>Während des Machine-Zustands Startup startet Prozess A (Idle -&gt; Running) und terminiert nach kurzer Ausführung selbsttätig (Running -&gt; Terminated, one shot).\n</li><li>Prozess B besitzt eine Startabhängigkeit (dependency) auf die Beendigung von Prozess A und wechselt nach dessen Termination von Idle nach Running; er verbleibt running über den Übergang in Machine State Running hinweg bis zum Übergang nach Diagnostics, wo er nach Terminated wechselt.\n</li><li>Beim Eintritt in Machine State Running startet Prozess C (Idle -&gt; Running) und terminiert ebenfalls beim Übergang zu Diagnostics.\n</li><li>Mit Eintritt der Function Group 1 in FG1:Running wird Prozess D gestartet (Idle -&gt; Running) und terminiert beim Verlassen von FG1:Running wieder nach Terminated.\n</li><li>Prozess E startet bei Eintritt in FG1:Running (Idle -&gt; Running) und referenziert zusätzlich FG2:Running; beim Übergang von FG2:Running nach FG2:Fallback terminiert Prozess E.\n</li><li>Prozess F startet bei Eintritt in FG2:Running; beim Übergang von FG2:Running zu FG2:Fallback wird Prozess F mit geänderten StartupOptions (different StartupOptions) neu gestartet bzw. angepasst und terminiert beim Übergang von FG2:Fallback nach FG2:Off.\n</li></ul>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Für Entwickler und Integratoren verdeutlicht das Diagramm die Aktivierungs- und Terminierungsregeln für Prozesse unter Execution Management:</p>\n<ul class=\"fig-list\"><li>Prozesse werden deklarativ an Zustände von Machine States oder Function Group States gebunden (reference).\n</li><li>Ausführungsabhängigkeiten (dependencies) verzögern den Start abhängiger Prozesse innerhalb desselben Systemzustands, bis Vorgängerprozesse erfolgreich initialisiert oder terminiert sind.\n</li><li>Zustandswechsel übergeordneter Funktionsgruppen erzwingen das Starten, Terminieren oder Neustarten mit modifizierten Argumenten/Optionen (different StartupOptions) der zugeordneten Prozesse.\n</li><li>Schraffierte Phasen markieren Transitionsintervalle, in denen das Execution Management Prozesse kontrolliert hoch- bzw. herunterfährt, bevor der Zielzustand als erreicht gilt.\n</li></ul>", "model": "gemini-3.8-flash (via agy)"}, {"id": "FIG-b67a615687d23127", "releases": ["R18-10-1", "R18-10_R4.4.0_R1.5.0"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">Timing- und Zustandsdiagramm zur Darstellung der zustandsabhängigen Prozesssteuerung (State Dependent Process Control) innerhalb des Execution Management (EM) der AUTOSAR Adaptive Platform. Das Diagramm ordnet die Lebenszyklen und Ausführungszustände von Prozessen den Zuständen der Machine (Machine State) sowie den Zuständen übergeordneter Funktionsgruppen (Function Group State) über einer gemeinsamen horizontalen Zeitachse (t) zu.</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<p class=\"fig-p\">Das Diagramm gliedert sich in Steuerungsebenen und Prozessverläufe:</p>\n<ul class=\"fig-list\"><li>Machine State: Enthält die Zustände Startup, Running, Diagnostics und Shutdown, getrennt durch schraffierte Übergangsphasen (state transition).\n</li><li>Function Group 1 State: Enthält die Zustände FG1:Off, FG1:Running und FG1:Off, getrennt durch schraffierte Zustandsübergänge.\n</li><li>Function Group 2 State: Enthält die Zustände FG2:Off, FG2:Running, FG2:Fallback, FG2:Off, FG2:Diag und FG2:Off, jeweils getrennt durch schraffierte Übergänge.\n</li><li>Prozesse A bis F: Prozesse der Plattform bzw. von Anwendungen mit den drei diskreten Ausführungszuständen Idle, Running und Terminated.\n</li><li>Annotationen und Beziehungen: Referenzen (reference) von Prozessen auf bestimmte Zustände (Startup, Running, FG1:Running, FG2:Running, FG2:Fallback), Startabhängigkeiten (dependency), Kennzeichnung eines selbstterminierenden Prozesses (self-terminating) sowie Kennzeichnung abweichender Startparameter/Neustarts über Schnittmarken (different StartupOptions).\n</li></ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<ul class=\"fig-list\"><li>Während des Machine-Zustands Startup startet Prozess A (Idle -&gt; Running) und terminiert nach kurzer Ausführung selbsttätig (Running -&gt; Terminated, self-terminating).\n</li><li>Prozess B besitzt eine Startabhängigkeit (dependency) auf die Beendigung von Prozess A und wechselt nach dessen Termination von Idle nach Running; er verbleibt running über den Übergang in Machine State Running hinweg bis zum Übergang nach Diagnostics, wo er nach Terminated wechselt.\n</li><li>Beim Eintritt in Machine State Running startet Prozess C (Idle -&gt; Running) und terminiert ebenfalls beim Übergang zu Diagnostics.\n</li><li>Mit Eintritt der Function Group 1 in FG1:Running wird Prozess D gestartet (Idle -&gt; Running) und terminiert beim Verlassen von FG1:Running wieder nach Terminated.\n</li><li>Prozess E startet bei Eintritt in FG1:Running (Idle -&gt; Running) und referenziert zusätzlich FG2:Running; beim Übergang von FG2:Running nach FG2:Fallback terminiert Prozess E.\n</li><li>Prozess F startet bei Eintritt in FG2:Running; beim Übergang von FG2:Running zu FG2:Fallback wird Prozess F mit geänderten StartupOptions (different StartupOptions) neu gestartet bzw. angepasst und terminiert beim Übergang von FG2:Fallback nach FG2:Off.\n</li></ul>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Für Entwickler und Integratoren verdeutlicht das Diagramm die Aktivierungs- und Terminierungsregeln für Prozesse unter Execution Management:</p>\n<ul class=\"fig-list\"><li>Prozesse werden deklarativ an Zustände von Machine States oder Function Group States gebunden (reference).\n</li><li>Ausführungsabhängigkeiten (dependencies) verzögern den Start abhängiger Prozesse innerhalb desselben Systemzustands, bis Vorgängerprozesse erfolgreich initialisiert oder terminiert sind.\n</li><li>Zustandswechsel übergeordneter Funktionsgruppen erzwingen das Starten, Terminieren oder Neustarten mit modifizierten Argumenten/Optionen (different StartupOptions) der zugeordneten Prozesse.\n</li><li>Schraffierte Phasen markieren Transitionsintervalle, in denen das Execution Management Prozesse kontrolliert hoch- bzw. herunterfährt, bevor der Zielzustand als erreicht gilt.\n</li></ul>", "model": "gemini-3.8-flash (via agy)"}, {"id": "FIG-52cd428811dc22b6", "releases": ["R19-03", "R19-11"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">Timing- und Zustandsdiagramm zur Darstellung der zustandsabhängigen Prozesssteuerung (State Dependent Process Control) innerhalb des Execution Management (EM) der AUTOSAR Adaptive Platform. Das Diagramm ordnet die Lebenszyklen und Ausführungszustände von Prozessen den Zuständen der Machine (Machine State) sowie den Zuständen übergeordneter Funktionsgruppen (Function Group State) über einer gemeinsamen horizontalen Zeitachse (t) zu.</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<p class=\"fig-p\">Das Diagramm gliedert sich in Steuerungsebenen und Prozessverläufe:</p>\n<ul class=\"fig-list\"><li>Machine State: Enthält die Zustände Off, Startup, Running, Diagnostics und Shutdown, getrennt durch schraffierte Übergangsphasen (state transition).\n</li><li>Function Group 1 State: Enthält die Zustände FG1:Off, FG1:Running und FG1:Off, getrennt durch schraffierte Zustandsübergänge.\n</li><li>Function Group 2 State: Enthält die Zustände FG2:Off, FG2:Running, FG2:Fallback, FG2:Off, FG2:Diag und FG2:Off, jeweils getrennt durch schraffierte Übergänge.\n</li><li>Prozesse A bis F: Prozesse der Plattform bzw. von Anwendungen mit den drei diskreten Ausführungszuständen Idle, Running und Terminated.\n</li><li>Annotationen und Beziehungen: Referenzen (reference) von Prozessen auf bestimmte Zustände (Startup, Running, FG1:Running, FG2:Running, FG2:Fallback), Startabhängigkeiten (dependency), Kennzeichnung eines selbstterminierenden Prozesses (self-terminating) sowie Kennzeichnung abweichender Startparameter/Neustarts über Schnittmarken (different StartupOptions).\n</li></ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<ul class=\"fig-list\"><li>Im Machine State Off verbleiben alle Prozesse im Zustand Idle.\n</li><li>Während des Machine-Zustands Startup startet Prozess A (Idle -&gt; Running) und terminiert nach kurzer Ausführung selbsttätig (Running -&gt; Terminated, self-terminating).\n</li><li>Prozess B besitzt eine Startabhängigkeit (dependency) auf die Beendigung von Prozess A und wechselt nach dessen Termination von Idle nach Running; er verbleibt running über den Übergang in Machine State Running hinweg bis zum Übergang nach Diagnostics, wo er nach Terminated wechselt.\n</li><li>Beim Eintritt in Machine State Running startet Prozess C (Idle -&gt; Running) und terminiert ebenfalls beim Übergang zu Diagnostics.\n</li><li>Mit Eintritt der Function Group 1 in FG1:Running wird Prozess D gestartet (Idle -&gt; Running) und terminiert beim Verlassen von FG1:Running wieder nach Terminated.\n</li><li>Prozess E startet bei Eintritt in FG1:Running (Idle -&gt; Running) und referenziert zusätzlich FG2:Running; beim Übergang von FG2:Running nach FG2:Fallback terminiert Prozess E.\n</li><li>Prozess F startet bei Eintritt in FG2:Running; beim Übergang von FG2:Running zu FG2:Fallback wird Prozess F mit geänderten StartupOptions (different StartupOptions) neu gestartet bzw. angepasst und terminiert beim Übergang von FG2:Fallback nach FG2:Off.\n</li></ul>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Für Entwickler und Integratoren verdeutlicht das Diagramm die Aktivierungs- und Terminierungsregeln für Prozesse unter Execution Management:</p>\n<ul class=\"fig-list\"><li>Prozesse werden deklarativ an Zustände von Machine States oder Function Group States gebunden (reference).\n</li><li>Ausführungsabhängigkeiten (dependencies) verzögern den Start abhängiger Prozesse innerhalb desselben Systemzustands, bis Vorgängerprozesse erfolgreich initialisiert oder terminiert sind.\n</li><li>Zustandswechsel übergeordneter Funktionsgruppen erzwingen das Starten, Terminieren oder Neustarten mit modifizierten Argumenten/Optionen (different StartupOptions) der zugeordneten Prozesse.\n</li><li>Schraffierte Phasen markieren Transitionsintervalle, in denen das Execution Management Prozesse kontrolliert hoch- bzw. herunterfährt, bevor der Zielzustand als erreicht gilt.\n</li></ul>", "model": "gemini-3.8-flash (via agy)"}, {"id": "FIG-8d040742c69f8dbb", "releases": ["R20-11"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">Timing- und Zustandsdiagramm zur Darstellung der zustandsabhängigen Prozesssteuerung (State Dependent Process Control) innerhalb des Execution Management (EM) der AUTOSAR Adaptive Platform. Das Diagramm ordnet die Lebenszyklen und Ausführungszustände von Prozessen den Zuständen der Machine (Machine State) sowie den Zuständen übergeordneter Funktionsgruppen (Function Group State) über einer gemeinsamen horizontalen Zeitachse (t) zu.</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<p class=\"fig-p\">Das Diagramm gliedert sich in Steuerungsebenen und Prozessverläufe:</p>\n<ul class=\"fig-list\"><li>Machine State: Enthält die Zustände Off, Startup, Running, Diagnostics und Shutdown, getrennt durch schraffierte Übergangsphasen (state transition).\n</li><li>Function Group 1 State: Enthält die Zustände FG1:Off, FG1:Running und FG1:Off, getrennt durch schraffierte Zustandsübergänge.\n</li><li>Function Group 2 State: Enthält die Zustände FG2:Off, FG2:Running, FG2:Fallback, FG2:Off, FG2:Diag und FG2:Off, jeweils getrennt durch schraffierte Übergänge.\n</li><li>Prozesse A bis F: Prozesse der Plattform bzw. von Anwendungen mit den drei diskreten Ausführungszuständen Idle, Running und Terminated.\n</li><li>Annotationen und Beziehungen: Referenzen (reference) von Prozessen auf bestimmte Zustände (Startup, Running, FG1:Running, FG2:Running, FG2:Fallback), Startabhängigkeiten (dependency), Kennzeichnung eines selbstterminierenden Prozesses (self-terminating) sowie Kennzeichnung abweichender Startparameter/Neustarts über Schnittmarken (different StartupOptions).\n</li></ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<ul class=\"fig-list\"><li>Im Machine State Off verbleiben alle Prozesse im Zustand Idle.\n</li><li>Während des Machine-Zustands Startup startet Prozess A (Idle -&gt; Running) und terminiert nach kurzer Ausführung selbsttätig (Running -&gt; Terminated, self-terminating).\n</li><li>Prozess B besitzt eine Startabhängigkeit (dependency) auf die Beendigung von Prozess A und wechselt nach dessen Termination von Idle nach Running; er verbleibt running über den Übergang in Machine State Running hinweg bis zum Übergang nach Diagnostics, wo er nach Terminated wechselt.\n</li><li>Beim Eintritt in Machine State Running startet Prozess C (Idle -&gt; Running) und terminiert ebenfalls beim Übergang zu Diagnostics.\n</li><li>Mit Eintritt der Function Group 1 in FG1:Running wird Prozess D gestartet (Idle -&gt; Running) und terminiert beim Verlassen von FG1:Running wieder nach Terminated.\n</li><li>Prozess E startet bei Eintritt in FG1:Running (Idle -&gt; Running) und referenziert zusätzlich FG2:Running; beim Übergang von FG2:Running nach FG2:Fallback terminiert Prozess E.\n</li><li>Prozess F startet bei Eintritt in FG2:Running; beim Übergang von FG2:Running zu FG2:Fallback wird Prozess F mit geänderten StartupOptions (different StartupOptions) neu gestartet bzw. angepasst und terminiert beim Übergang von FG2:Fallback nach FG2:Off.\n</li></ul>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Für Entwickler und Integratoren verdeutlicht das Diagramm die Aktivierungs- und Terminierungsregeln für Prozesse unter Execution Management:</p>\n<ul class=\"fig-list\"><li>Prozesse werden deklarativ an Zustände von Machine States oder Function Group States gebunden (reference).\n</li><li>Ausführungsabhängigkeiten (dependencies) verzögern den Start abhängiger Prozesse innerhalb desselben Systemzustands, bis Vorgängerprozesse erfolgreich initialisiert oder terminiert sind.\n</li><li>Zustandswechsel übergeordneter Funktionsgruppen erzwingen das Starten, Terminieren oder Neustarten mit modifizierten Argumenten/Optionen (different StartupOptions) der zugeordneten Prozesse.\n</li><li>Schraffierte Phasen markieren Transitionsintervalle, in denen das Execution Management Prozesse kontrolliert hoch- bzw. herunterfährt, bevor der Zielzustand als erreicht gilt.\n</li></ul>", "model": "gemini-3.8-flash (via agy)"}, {"id": "FIG-395171aad1d9c101", "releases": ["R21-11"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">Timing- und Zustandsdiagramm zur Darstellung der zustandsabhängigen Prozesssteuerung (State Dependent Process Control) innerhalb des Execution Management (EM) der AUTOSAR Adaptive Platform. Das Diagramm ordnet die Lebenszyklen und Ausführungszustände von Prozessen den Zuständen der Machine (Machine State) sowie den Zuständen übergeordneter Funktionsgruppen (Function Group State) über einer gemeinsamen horizontalen Zeitachse (t) zu.</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<p class=\"fig-p\">Das Diagramm gliedert sich in Steuerungsebenen und Prozessverläufe:</p>\n<ul class=\"fig-list\"><li>Machine State: Enthält die Zustände Off, Startup, Running, Diagnostics und Shutdown, getrennt durch schraffierte Übergangsphasen (state transition).\n</li><li>Function Group 1 State: Enthält die Zustände FG1:Off, FG1:Running und FG1:Off, getrennt durch schraffierte Zustandsübergänge.\n</li><li>Function Group 2 State: Enthält die Zustände FG2:Off, FG2:Running, FG2:Fallback, FG2:Off, FG2:Diag und FG2:Off, jeweils getrennt durch schraffierte Übergänge.\n</li><li>Prozesse A bis F: Prozesse der Plattform bzw. von Anwendungen mit den drei diskreten Ausführungszuständen Idle, Running und Terminated.\n</li><li>Annotationen und Beziehungen: Referenzen (reference) von Prozessen auf bestimmte Zustände (Startup, Running, FG1:Running, FG2:Running, FG2:Fallback), Startabhängigkeiten (dependency), Kennzeichnung eines selbstterminierenden Prozesses (self-terminating) sowie Kennzeichnung abweichender Startparameter/Neustarts über Schnittmarken (different StartupOptions).\n</li></ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<ul class=\"fig-list\"><li>Im Machine State Off verbleiben alle Prozesse im Zustand Idle.\n</li><li>Während des Machine-Zustands Startup startet Prozess A (Idle -&gt; Running) und terminiert nach kurzer Ausführung selbsttätig (Running -&gt; Terminated, self-terminating).\n</li><li>Prozess B besitzt eine Startabhängigkeit (dependency) auf die Beendigung von Prozess A und wechselt nach dessen Termination von Idle nach Running; beim Übergang von Machine State Startup nach Running erfährt Prozess B eine Anpassung bzw. einen Neustart mit abweichenden Startup-Optionen (different StartupOptions, markiert durch Zacken-Symbol) und läuft anschließend bis zum Übergang nach Diagnostics weiter, wo er nach Terminated wechselt.\n</li><li>Beim Eintritt in Machine State Running startet Prozess C (Idle -&gt; Running) und terminiert ebenfalls beim Übergang zu Diagnostics.\n</li><li>Mit Eintritt der Function Group 1 in FG1:Running wird Prozess D gestartet (Idle -&gt; Running) und terminiert beim Verlassen von FG1:Running wieder nach Terminated.\n</li><li>Prozess E startet bei Eintritt in FG1:Running (Idle -&gt; Running) und referenziert zusätzlich FG2:Running; beim Übergang von FG2:Running nach FG2:Fallback terminiert Prozess E.\n</li><li>Prozess F startet bei Eintritt in FG2:Running; beim Übergang von FG2:Running zu FG2:Fallback wird Prozess F mit geänderten StartupOptions (different StartupOptions) neu gestartet bzw. angepasst und terminiert beim Übergang von FG2:Fallback nach FG2:Off.\n</li></ul>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Für Entwickler und Integratoren verdeutlicht das Diagramm die Aktivierungs- und Terminierungsregeln für Prozesse unter Execution Management:</p>\n<ul class=\"fig-list\"><li>Prozesse werden deklarativ an Zustände von Machine States oder Function Group States gebunden (reference).\n</li><li>Ausführungsabhängigkeiten (dependencies) verzögern den Start abhängiger Prozesse innerhalb desselben Systemzustands, bis Vorgängerprozesse erfolgreich initialisiert oder terminiert sind.\n</li><li>Zustandswechsel übergeordneter Funktionsgruppen oder der Machine State können die Ausführung von Prozessen beeinflussen und über different StartupOptions eine Rekonfiguration bzw. einen Neustart mit veränderten Argumenten/Optionen auslösen (wie für Prozess B beim Machine-State-Wechsel Startup -&gt; Running und für Prozess F beim Function-Group-Wechsel FG2:Running -&gt; FG2:Fallback gezeigt).\n</li><li>Schraffierte Phasen markieren Transitionsintervalle, in denen das Execution Management Prozesse kontrolliert hoch- bzw. herunterfährt, bevor der Zielzustand als erreicht gilt.\n</li></ul>", "model": "gemini-3.8-flash (via agy)"}, {"id": "FIG-5f5a5175ab2cdb97", "releases": ["R22-11", "R23-11"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">Timing- und Zustandsdiagramm zur Darstellung der zustandsabhängigen Prozesssteuerung (State Dependent Process Control) innerhalb des Execution Management (EM) der AUTOSAR Adaptive Platform. Das Diagramm ordnet die Lebenszyklen und Ausführungszustände von Prozessen den Zuständen der Machine (Machine State) sowie den Zuständen übergeordneter Funktionsgruppen (Function Group State) über einer gemeinsamen horizontalen Zeitachse (t) zu.</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<p class=\"fig-p\">Das Diagramm gliedert sich in Steuerungsebenen und Prozessverläufe:</p>\n<ul class=\"fig-list\"><li>Machine State: Enthält die Zustände Off, Startup, Running, Diagnostics und Shutdown, getrennt durch schraffierte Übergangsphasen (state transition).\n</li><li>Function Group 1 State: Enthält die Zustände FG1:Off, FG1:Running und FG1:Off, getrennt durch schraffierte Zustandsübergänge.\n</li><li>Function Group 2 State: Enthält die Zustände FG2:Off, FG2:Running, FG2:Fallback, FG2:Off, FG2:Diag und FG2:Off, jeweils getrennt durch schraffierte Übergänge.\n</li><li>Prozesse A bis F: Prozesse der Plattform bzw. von Anwendungen mit den drei diskreten Ausführungszuständen Idle, Running und Terminated.\n</li><li>Annotationen und Beziehungen: Referenzen (reference) von Prozessen auf bestimmte Zustände (Startup, Running, FG1:Running, FG2:Running, FG2:Fallback), Startabhängigkeiten (dependency), Kennzeichnung eines selbstterminierenden Prozesses (self-terminating) sowie Kennzeichnung abweichender Startparameter/Neustarts über Schnittmarken (different StartupOptions).\n</li></ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<ul class=\"fig-list\"><li>Im Machine State Off verbleiben alle Prozesse im Zustand Idle.\n</li><li>Während des Machine-Zustands Startup startet Prozess A (Idle -&gt; Running) und terminiert nach kurzer Ausführung selbsttätig (Running -&gt; Terminated, self-terminating).\n</li><li>Prozess B besitzt eine Startabhängigkeit (dependency) auf die Beendigung von Prozess A und wechselt nach dessen Termination von Idle nach Running; beim Übergang von Machine State Startup nach Running erfährt Prozess B eine Anpassung bzw. einen Neustart mit abweichenden Startup-Optionen (different StartupOptions, markiert durch Zacken-Symbol) und läuft anschließend bis zum Übergang nach Diagnostics weiter, wo er nach Terminated wechselt.\n</li><li>Beim Eintritt in Machine State Running startet Prozess C (Idle -&gt; Running) und terminiert ebenfalls beim Übergang zu Diagnostics.\n</li><li>Mit Eintritt der Function Group 1 in FG1:Running wird Prozess D gestartet (Idle -&gt; Running) und terminiert beim Verlassen von FG1:Running wieder nach Terminated.\n</li><li>Prozess E startet bei Eintritt in FG1:Running (Idle -&gt; Running) und referenziert zusätzlich FG2:Running; beim Übergang von FG2:Running nach FG2:Fallback terminiert Prozess E.\n</li><li>Prozess F startet bei Eintritt in FG2:Running; beim Übergang von FG2:Running zu FG2:Fallback wird Prozess F mit geänderten StartupOptions (different StartupOptions) neu gestartet bzw. angepasst und terminiert beim Übergang von FG2:Fallback nach FG2:Off.\n</li></ul>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Für Entwickler und Integratoren verdeutlicht das Diagramm die Aktivierungs- und Terminierungsregeln für Prozesse unter Execution Management:</p>\n<ul class=\"fig-list\"><li>Prozesse werden deklarativ an Zustände von Machine States oder Function Group States gebunden (reference).\n</li><li>Ausführungsabhängigkeiten (dependencies) verzögern den Start abhängiger Prozesse innerhalb desselben Systemzustands, bis Vorgängerprozesse erfolgreich initialisiert oder terminiert sind.\n</li><li>Zustandswechsel übergeordneter Funktionsgruppen oder der Machine State können die Ausführung von Prozessen beeinflussen und über different StartupOptions eine Rekonfiguration bzw. einen Neustart mit veränderten Argumenten/Optionen auslösen (wie für Prozess B beim Machine-State-Wechsel Startup -&gt; Running und für Prozess F beim Function-Group-Wechsel FG2:Running -&gt; FG2:Fallback gezeigt).\n</li><li>Schraffierte Phasen markieren Transitionsintervalle, in denen das Execution Management Prozesse kontrolliert hoch- bzw. herunterfährt, bevor der Zielzustand als erreicht gilt.\n</li></ul>", "model": "gemini-3.8-flash (via agy)"}], "trans": [{"from": "FIG-6a45d8754bdc72b8", "to": "FIG-c6b898406a2ae201", "fr": "R17-10_R1.2.0", "tr": "R18-03_R1.4.0", "change": "keine", "label": "keine inhaltliche Änderung", "html": "<p class=\"fig-p\">Keine inhaltlichen Änderungen erkennbar.</p>"}, {"from": "FIG-c6b898406a2ae201", "to": "FIG-b67a615687d23127", "fr": "R18-03_R1.4.0", "tr": "R18-10-1", "change": "redaktionell", "label": "redaktionell", "html": "<ul class=\"fig-list\"><li>Anmerkung an der Zustandsänderung von Prozess A: Textbeschriftung von „one shot“ zu „self-terminating“ geändert.\n</li></ul>"}, {"from": "FIG-b67a615687d23127", "to": "FIG-52cd428811dc22b6", "fr": "R18-10_R4.4.0_R1.5.0", "tr": "R19-03", "change": "normativ", "label": "normative Änderung", "html": "<ul class=\"fig-list\"><li>Machine State: Vor dem Zustand „Startup“ ist nun der Zustand „Off“ mit nachfolgendem schraffierten Zustandsübergang („state transition“) eingefügt.\n</li></ul>"}, {"from": "FIG-52cd428811dc22b6", "to": "FIG-8d040742c69f8dbb", "fr": "R19-11", "tr": "R20-11", "change": "keine", "label": "keine inhaltliche Änderung", "html": "<p class=\"fig-p\">Keine inhaltlichen Änderungen erkennbar.</p>"}, {"from": "FIG-8d040742c69f8dbb", "to": "FIG-395171aad1d9c101", "fr": "R20-11", "tr": "R21-11", "change": "normativ", "label": "normative Änderung", "html": "<ul class=\"fig-list\"><li>Prozess B: Beim Übergang von Machine State „Startup“ nach „Running“ wurde ein Zacken-/Unterbrechungssymbol („different StartupOptions“) in den Verlauf des Zustands „Running“ eingefügt.\n</li></ul>"}, {"from": "FIG-395171aad1d9c101", "to": "FIG-5f5a5175ab2cdb97", "fr": "R21-11", "tr": "R22-11", "change": "keine", "label": "keine inhaltliche Änderung", "html": "<p class=\"fig-p\">Keine inhaltlichen Änderungen erkennbar.</p>"}]};
